def test_relay_adds_5_bits():
    """Relay format should be exactly 5 bits longer than non-relay."""
    p = {'methodName': 'RPC_Int', 'params': [42], 'viewId': 1,
         'rpcCounter': 0, 'mode': RPCMode.Others}
    _, normal_bits = encode_rpc_subsequent(
        p['methodName'], p['params'], p['viewId'], p['rpcCounter'], p['mode'],
        target_view=0x2000)
    _, relay_bits = encode_rpc_subsequent(
        p['methodName'], p['params'], p['viewId'], p['rpcCounter'], p['mode'],
        target_view=0x2000, relay=True)
    assert relay_bits - normal_bits == 5

    _, normal_bits_fu = encode_rpc_first_use(
        p['methodName'], p['params'], p['viewId'], p['rpcCounter'], p['mode'],
        target_view=0x2000)
    _, relay_bits_fu = encode_rpc_first_use(
        p['methodName'], p['params'], p['viewId'], p['rpcCounter'], p['mode'],
        target_view=0x2000, relay=True)
    assert relay_bits_fu - normal_bits_fu == 5


def test_relay_decodes_correctly():
    """Relay-encoded RPCs should still decode with correct params."""
    entry = GOLDEN_RELAY['sub_int_42_relay']
    raw = bytes.fromhex(entry['hex'])
    decoded = decode_rpc(raw, entry['bits'])
    assert decoded['rpc_counter'] == 0
    assert decoded['method_name'] == 'RPC_Int'


def test_ts_golden_decodes_correctly():
    """All golden TS values decode to expected fields in Python."""
    for name, entry in GOLDEN.items():
        raw = bytes.fromhex(entry['hex'])
        decoded = decode_rpc(raw, entry['bits'])
        p = entry['params']
        assert decoded['rpc_counter'] == p['rpcCounter'], \
            f"{name}: counter {decoded['rpc_counter']} != {p['rpcCounter']}"
        assert decoded['method_name'] == p['methodName'], \
            f"{name}: method {decoded['method_name']} != {p['methodName']}"
        if p['params']:
            assert decoded['params'] == p['params'], \
                f"{name}: params {decoded['params']} != {p['params']}"


def test_target_view_0x2000_in_wire():
    """The 0x2000 constant appears in the wire format at the expected position."""
    data, bits = _encode(GOLDEN['sub_int_42'])
    all_bits = ''.join(f'{b:08b}' for b in data)
    const_start = 120
    const_val = int(all_bits[const_start:const_start + 16], 2)
    assert const_val == 0x2000, f"Expected 0x2000, got 0x{const_val:04x}"


def test_16bit_counter_in_wire():
    """Counter=500 is encoded as raw 16-bit value 0x01F4 in the wire format."""
    data, _ = _encode(GOLDEN['sub_int_42_c500'])
    assert data[7] == 0x01  # high byte
    assert data[8] == 0xF4  # low byte


GOLDEN_BATCH = {
    'rpc_int_0x60': {
        'hex': '07000000200649d93b6ad8ea2b60',
        'bits': 110,
        'methodName': 'RPC_Int',
        'methodIndex': 0x60,
    },
    'rpc_void_4': {
        'hex': '07000000240649d93b6ad8aaf42384',
        'bits': 118,
        'methodName': 'RPC_Void',
        'methodIndex': 4,
    },
}


def test_batch_index_encode_matches_ts():
    for name, entry in GOLDEN_BATCH.items():
        data, bits = encode_batch_index(entry['methodName'], entry['methodIndex'])
        assert data.hex() == entry['hex'], \
            f"{name}: hex {data.hex()} != {entry['hex']}"
        assert bits == entry['bits'], \
            f"{name}: bits {bits} != {entry['bits']}"


def test_batch_index_decode_matches_ts():
    for name, entry in GOLDEN_BATCH.items():
        raw = bytes.fromhex(entry['hex'])
        decoded = decode_batch_index(raw)
        assert decoded is not None, f"{name}: decode returned None"
        assert decoded['method_name'] == entry['methodName'], \
            f"{name}: method {decoded['method_name']} != {entry['methodName']}"
        assert decoded['method_index'] == entry['methodIndex'], \
            f"{name}: index {decoded['method_index']} != {entry['methodIndex']}"


if __name__ == '__main__':
    import traceback
    tests = [v for k, v in sorted(globals().items()) if k.startswith('test_')]
    passed = failed = 0
    for t in tests:
        try:
            t()
            passed += 1
            print(f'  PASS  {t.__name__}')
        except Exception as e:
            failed += 1
            print(f'  FAIL  {t.__name__}: {e}')
            traceback.print_exc()
    print(f'\n{passed} passed, {failed} failed')
    sys.exit(1 if failed else 0)
